@propertyWrapper
struct Trimmed {
    private var text: String = ""
    var wrappedValue: String {
        get { text }
        set { text = newValue.trimmingCharacters(in: .whitespaces) }
    }
    init(wrappedValue: String) {
        self.wrappedValue = wrappedValue
    }
}

struct FormInput {
    @Trimmed var username: String
}

var input = FormInput(username: "   Taylor   ")
print("#\(input.username)#")

@propertyWrapper
struct ValidatedNumber {
    private var num: Int = 0
    var projectedValue: Bool = false

    var wrappedValue: Int {
        get { num }
        set {
            if newValue >= 0 {
                num = newValue
                projectedValue = true
            } else {
                projectedValue = false
            }
        }
    }

    init(wrappedValue: Int) {
        self.wrappedValue = wrappedValue
    }
}

struct Account {
    @ValidatedNumber var balance: Int = 100
}

var acc = Account()
acc.balance = -50
print("balance: \(acc.balance), valid: \(acc.$balance)")

